def men(**k):
    d = dict(n=100, seed=7, x0=200, x1=1100, y0=780, y1=1010, hFar=72, hNear=128, face=1)
    d.update(k); return d
def hud(*steps): return {"count": [[t, c] for t, c in steps]}
def bgp(p, **k): return dict(img=p, **k)
def grow(z0, z1, d, **k): return dict(z=[[0, z0], [d, z1]], **k)

# lineup of predators small -> large, in shadow
LINE = [("vraptor2_1", 55), ("direwolf_1", 90), ("kelenken_1", 230), ("smilodon_0", 130), ("utah_3", 210), ("arctodus_5", 170), ("trex_4", 420), ("giga_3", 380)]
def lineup(p, d, dark=0.55, pan=(0, 0), z=(1.0, 1.06), names=LINE, x0=170, step=230):
    bs = [B(n, -1, h=h, x=x0 + k * step + (60 if h > 300 else 0), y=900, dark=dark, alpha=[[0, 0], [0.15 + k * 0.18, 0], [0.5 + k * 0.18, 1]], ph=k) for k, (n, h) in enumerate(names)]
    return A(bg=bgp(p), beasts=bs, split=2000, cam=dict(z=[[0, z[0]], [d, z[1]]], x=[[0, pan[0]], [d, pan[1]]]), grade=["#0b1016", 0.35], vig=0.65)

def board_gap(k, tiles_after=True):
    """Tier-board drop then the round card, filling the silent gap before card k."""
    g = C[k]
    return [(g["gap"], BD(ov=both(FIN(0.3), FOUT(0.35)))), (g["card"], CARD(k, CARD_BG[k]))]
